SELECT lot_id, destination, units_listed, seller_ask_cents, freight_quote_cents, seller_ask_cents + freight_quote_cents AS ask_plus_freight_cents, round((seller_ask_cents + freight_quote_cents)/100.0/units_listed, 4) AS ask_plus_freight_usd_per_listed_unit, seller_ask_cents + freight_quote_cents - first_shipment_credit_cents AS conditional_first_shipment_subtotal_cents, freight_quote_cents - min(freight_quote_cents) OVER () AS excess_freight_vs_lowest_cents, buyer_bid_cents, other_costs_cents, CAST(NULL AS BIGINT) AS full_landed_cost_cents, CAST(NULL AS BIGINT) AS contribution_cents, quote_id, quote_source, seller_source FROM read_json_auto('/Users/nickgonzales/Developer/Bonfyre/packs/wholesale-20k/evidence/houston-route-input-20261009.json') ORDER BY freight_quote_cents;
